function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const brands = ['Lenovo', 'Samsung', 'LG', 'HP', 'Apple'];
  const day = (y, m, d) => new Date(Date.UTC(y, m - 1, d)).toISOString().slice(0, 10);
  const Users = [], Orders = [], Items = [];
  const userCount = size === 'small' ? pick(6) : 600;
  const itemCount = size === 'small' ? 1 + pick(4) : 200;
  const orderCount = userCount === 0 ? 0 : size === 'small' ? pick(9) : 2000;
  for (let id = 1; id <= userCount; id++) Users.push([id, day(2018, 1 + pick(12), 1 + pick(28)), brands[pick(brands.length)]]);
  for (let id = 1; id <= itemCount; id++) Items.push([id, brands[pick(brands.length)]]);
  // Small cases cluster dates at the year boundaries; large cases spread over 2018-2020.
  const edges = ['2018-08-04', '2018-12-31', '2019-01-01', '2019-06-15', '2019-12-31', '2020-01-01'];
  for (let id = 1; id <= orderCount; id++) {
    const date = size === 'small' ? edges[pick(edges.length)] : day(2018 + pick(3), 1 + pick(12), 1 + pick(28));
    Orders.push([id, date, 1 + pick(itemCount), 1 + pick(userCount), 1 + pick(userCount)]);
  }
  return [{ Users, Orders, Items }];
}
